            new ContextMenuItem()
            {
                Text = "Group",
                Id = "group",
                IconCss = "e-group"
            }
        };
    }
    private void BeforeOpen(DiagramBeforeMenuOpenEventArgs args)
    {
        // Handle context menu opening logic
    }
    private void ItemClicked(DiagramMenuEventArgs args)
    {
        // Handle menu item click events
    }
}

